contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable {
        require(receiver == address(this), "receiver must be this contract");
        require(amount == 0, "amount must be zero");
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted);
    }

    receive() external payable {
        revert("no ether accepted");
    }
}

